<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { listarAnulados, restaurarDocumento } from '../services/documentos'
import type { CatalogOption, HistorialDocumento } from '../../interfaces/documento'
const filters=reactive({criterio:'',tipo_documento_id:0,estado:'',page:1}), items=ref<HistorialDocumento[]>([]), tipos=ref<CatalogOption[]>([])
const context=reactive<{instancia?:CatalogOption|null;cargo?:CatalogOption|null;usuarioId?:number}>({}), pagination=reactive({current:1,last:1,total:0})
const loading=ref(false),actionLoading=ref(0),error=ref(''),success=ref(''),detail=ref<HistorialDocumento|null>(null)
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarAnulados(filters);items.value=r.data;tipos.value=r.filtros.tipos_documento;context.instancia=r.contexto.instancia_activa;context.cargo=r.contexto.cargo_activo;context.usuarioId=r.contexto.usuario_id;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudieron cargar los documentos.'}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',tipo_documento_id:0,estado:''});void load()}
function number(i:HistorialDocumento){return i.documento.numero_completo||i.documento.numero||`Documento #${i.documento_id}`}
function date(value?:string|null){return value?new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'—'}
function canRestore(i:HistorialDocumento){return !context.usuarioId||i.usuario_origen?.id===context.usuarioId}
async function restore(i:HistorialDocumento){const rejected=i.estado.toUpperCase()==='RECHAZADO';actionLoading.value=i.id;error.value='';try{await restaurarDocumento(rejected?'rechazado':'anulado',rejected?i.id:i.documento_id);success.value=rejected?'Documento retornado a Por recepcionar.':'Documento retornado a Pendientes.';await load(filters.page)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo restaurar el documento.'}finally{actionLoading.value=0}}
onMounted(()=>load())
</script>
<template><div class="cancelled"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/tramite">Trámite V2</RouterLink> / Gestión de documentos / Anulados y rechazados</nav><header class="hero"><div class="mark">TR</div><div><small>Gestión de documentos</small><h1>Anulados y rechazados</h1><p>Consulta el seguimiento y recupera documentos en los que participaste.</p></div><aside v-if="context.instancia"><b>{{context.instancia.nombre}}</b><span>{{context.cargo?.nombre||'Cargo activo'}}</span></aside><strong v-if="pagination.total">{{pagination.total}}</strong></header><div v-if="success" class="flash">✓ {{success}} <button @click="success=''">×</button></div><form class="filters" @submit.prevent="load()"><label class="wide"><span>Número, asunto o código</span><input v-model.trim="filters.criterio" placeholder="Buscar documento"></label><label><span>Tipo documental</span><select v-model="filters.tipo_documento_id"><option :value="0">Todos</option><option v-for="o in tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Estado</span><select v-model="filters.estado"><option value="">Todos</option><option>ANULADO</option><option>RECHAZADO</option></select></label><div><button type="submit">Buscar</button><button type="button" class="clear" @click="clear">Limpiar</button></div></form><div v-if="error" class="notice error"><b>No se pudo obtener la información.</b><span>{{error}}</span><button @click="load(filters.page)">Reintentar</button></div><div v-else-if="loading" class="notice">Cargando documentos…</div><div v-else-if="!items.length" class="notice"><b>No hay documentos anulados o rechazados</b><span>Prueba modificando los criterios de búsqueda.</span></div><section v-else class="cards"><article v-for="i in items" :key="i.id" :class="i.estado.toLowerCase()"><header><div><small>{{i.documento.tipo_documento?.nombre||'Documento'}}</small><h2>{{number(i)}}</h2></div><span>{{i.estado}}</span></header><div class="body"><h3>{{i.documento.asunto}}</h3><dl><div><dt>Código único</dt><dd>{{i.codigounico||'—'}}</dd></div><div><dt>Trámite</dt><dd>{{i.tipo_tramite||'Original'}}</dd></div><div><dt>Origen</dt><dd>{{i.instancia_origen?.nombre||'—'}}</dd></div><div><dt>Destino</dt><dd>{{i.instancia_destino?.nombre||'—'}}</dd></div><div><dt>Fecha</dt><dd>{{date(i.fecha_recepcion||i.updated_at||i.created_at)}}</dd></div><div v-if="i.observacion"><dt>Observación</dt><dd>{{i.observacion}}</dd></div></dl></div><footer><button class="detail" @click="detail=i">Ver seguimiento</button><button v-if="canRestore(i)" class="restore" :disabled="actionLoading===i.id" @click="restore(i)">{{actionLoading===i.id?'Procesando…':i.estado.toUpperCase()==='ANULADO'?'Retornar a pendientes':'Retornar a recepcionar'}}</button></footer></article></section><footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer><div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal"><header><div><small>Seguimiento documental</small><h2>{{number(detail)}}</h2></div><button @click="detail=null">×</button></header><div><h3>{{detail.documento.asunto}}</h3><p><b>Estado:</b> {{detail.estado}}</p><p><b>Origen:</b> {{detail.instancia_origen?.nombre||'—'}} / {{detail.cargo_origen?.nombre||'—'}}</p><p><b>Destino:</b> {{detail.instancia_destino?.nombre||'—'}} / {{detail.cargo_destino?.nombre||'—'}}</p><p><b>Observación:</b> {{detail.observacion||detail.indicacion||'—'}}</p><small>El historial cronológico completo se incorporará en la pantalla transversal de detalle documental.</small></div></section></div></div></template>
